escopo=dict(ciclo='básico',justificativa=comp['onde_se_encaixa'],clinica_lateral=['mielina-clinica'],clinica_e_tema=False,motivo_tema='',ordem_da_fala=[b['laminas'] for b in blocks],historia=' '.join(b['processo'] for b in blocks),linha_logica=[dict(passo=b['titulo'],mecanismo=True,liga_ao_proximo=B[i+1][1] if i+1<len(B) else '',cards=[t['key'] for t in T if t['bloco']==i]) for i,b in enumerate(blocks)],cards_de_conexao=['circuito','mielinizadores','snc-snp','raizes','cinzenta-branca','redes'],provas=[],uso_das_fontes=dict(aula=[t['key'] for t in T],prova=[],bibliografia=['soma','tracadores'],apostila=['somatico-visceral','pseudounipolar','branca-rostral']))
(R/'escopo.json').write_text(json.dumps(escopo,ensure_ascii=False,indent=2))
(R/'percurso-aula.md').write_text('# Percurso\n\n'+'\n\n'.join('## '+b['titulo']+'\n\n'+b['processo'] for b in blocks)+'\n\n## Casos de fronteira\n\nDesmielinização: somente AnKing básico central/periférico,sem manejo. Broca e via piramidal já são exemplos explícitos do professor. Plexos: princípio de redistribuição,sem territórios musculares. Córtex e imagem: princípio de correspondência,sem lista de áreas ou sequências físicas. Aprofundamento de sinapse será da Fisiologia; aqui os componentes e o acoplamento entre células.\n')
print(len(T),'capacidades',len(B),'blocos')
